import{_ as r,c as a,o as t,ae as i}from"./chunks/framework.CXzlQjHd.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"README.md","filePath":"README.md"}'),o={name:"README.md"};function n(c,e,l,s,d,h){return t(),a("div",null,e[0]||(e[0]=[i('<h2 id="architectural-decisions" tabindex="-1">Architectural Decisions <a class="header-anchor" href="#architectural-decisions" aria-label="Permalink to &quot;Architectural Decisions&quot;">​</a></h2><p>The <code>architecture</code> folder comprises of subfolders and markdowns that documents the architectural decisions made when deciding on the tools used in developing this project. The template used is based on the simple and popular template -- <a href="https://cognitect.com/blog/2011/11/15/documenting-architecture-decisions" target="_blank" rel="noreferrer">Documenting architecture decisions - Michael Nygard</a>, however slightly modified to include the <strong>Date</strong> of the decision. The folder is updated continually when decision making need arises until the end of the project.</p><h2 id="folder-arrangement" tabindex="-1">Folder Arrangement <a class="header-anchor" href="#folder-arrangement" aria-label="Permalink to &quot;Folder Arrangement&quot;">​</a></h2><p>We follow the recommendations from Michael Nygard (quoted below) in the folder arrangement.</p><blockquote><p>ADRs will be numbered sequentially and monotonically. Numbers will not be reused.</p></blockquote><blockquote><p>If a decision is reversed, we will keep the old one around, but mark it as superseded. (It&#39;s still relevant to know that it was the decision, but is no longer the decision.)</p></blockquote><p>In the <code>architecture</code> folder there are subfolders for each decision making. In each subfolders, there are ADRs numbered sequentially. Also the numbers are reflected in the <em>Title</em> when you open the ADR.</p><h2 id="quick-links" tabindex="-1">Quick Links <a class="header-anchor" href="#quick-links" aria-label="Permalink to &quot;Quick Links&quot;">​</a></h2><ol><li><a href="./architecture/adr-choose-web-framework/adr1.html">Framework Decision</a></li><li><a href="./architecture/adr-choose-styling-library/adr1.html">Styling Library Decision</a></li><li><a href="./architecture/adr-choose-webmap-library/adr1.html">Web mapping Library Decision</a></li><li><a href="./architecture/adr-choose-drawing-library/adr1.html">Drawing Library Decision</a></li><li><a href="./architecture/adr-choose-package-manager/adr1.html">Package Manager Decision</a></li><li><a href="./architecture/adr-choose-language/adr1.html">Programming Language Decision</a></li><li><a href="./architecture/adr-choose-bundler/adr1.html">Bundler Decision</a></li></ol><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://github.com/joelparkerhenderson/architecture-decision-record?tab=readme-ov-file" target="_blank" rel="noreferrer">Architecture Decision Record</a></li><li><a href="https://cognitect.com/blog/2011/11/15/documenting-architecture-decisions" target="_blank" rel="noreferrer">Documenting architecture decisions - Michael Nygard</a></li></ul>',11)]))}const f=r(o,[["render",n]]);export{m as __pageData,f as default};
